public int[] asteroidCollision(int[] asteroids) {
    Deque<Integer> stack = new ArrayDeque<>();    // survivors so far
    for (int a : asteroids) {
        boolean alive = true;
        while (alive && a < 0 && !stack.isEmpty() && stack.peek() > 0) {
            int top = stack.peek();
            if (top < -a) stack.pop();             // the right-mover explodes
            else {
                if (top == -a) stack.pop();        // same size: both explode
                alive = false;                     // a explodes
            }
        }
        if (alive) stack.push(a);
    }
    int[] out = new int[stack.size()];
    for (int i = out.length - 1; i >= 0; i--) out[i] = stack.pop();   // bottom of the stack goes first
    return out;
}

